package com.zweetnekken;

import com.google.inject.Provides;
import com.zweetnekken.evidence.EventPipeline;
import com.zweetnekken.evidence.EvidenceStore;
import com.zweetnekken.events.CollectionLogEventListener;
import com.zweetnekken.events.CombatTierEventListener;
import com.zweetnekken.events.LootEventListener;
import com.zweetnekken.events.WeaponCreationEventListener;
import com.zweetnekken.events.PetEventListener;
import com.zweetnekken.pb.PersonalBestService;
import com.zweetnekken.progress.PlayerProgressService;
import com.zweetnekken.service.ZweetnekkenDataService;
import com.zweetnekken.service.BingoService;
import com.zweetnekken.service.EventAlertService;
import com.zweetnekken.service.ImageCache;
import com.zweetnekken.service.PartyTracker;
import com.zweetnekken.ui.ZweetnekkenPanel;
import com.zweetnekken.ui.BingoEventOverlay;
import com.zweetnekken.ui.EventAlertOverlay;
import java.io.IOException;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Filepath;

@Slf4j
@PluginDescriptor(
	name = "Zweetnekken",
	description = "Zweetnekken clan dashboard, evidence capture, loot submissions, and PB sync",
	tags = {"clan", "loot", "pvm", "personal best", "collection log", "pet"},
	internalName = "zweetnekken",
	legacyDataDirectory = "zweetnekken"
)
public class ZweetnekkenPlugin extends Plugin
{
	static final long PROFILE_AND_COMPETITIONS_REFRESH_MINUTES = 15;
	static final long PLAYER_PROGRESS_REFRESH_MINUTES = 30;
	static final long PLAYER_ELIGIBILITY_REFRESH_MINUTES = 1;

	@Inject private Client client;
	@Inject private ClientToolbar toolbar;
	@Inject private EventBus eventBus;
	@Inject private ScheduledExecutorService executor;
	@Inject private ClientThread clientThread;
	@Inject private OverlayManager overlayManager;
	@Inject private ZweetnekkenConfig config;
	@Inject private ConfigManager configManager;
	@Inject private ZweetnekkenPanel panel;
	@Inject private ZweetnekkenDataService data;
	@Inject private BingoService bingo;
	@Inject private EvidenceStore evidence;
	@Inject private EventPipeline pipeline;
	@Inject private ImageCache imageCache;
	@Inject private PersonalBestService pbs;
	@Inject private PlayerProgressService progress;
	@Inject private EventAlertService eventAlerts;
	@Inject private EventAlertOverlay eventAlertOverlay;
	@Inject private BingoEventOverlay bingoEventOverlay;
	@Inject private PartyTracker parties;
	@Inject private LootEventListener loot;
	@Inject private WeaponCreationEventListener weaponCreation;
	@Inject private CollectionLogEventListener collectionLog;
	@Inject private PetEventListener pets;
	@Inject private CombatTierEventListener combatTiers;
	private NavigationButton navigation;
	private ScheduledFuture<?> refreshTask;
	private ScheduledFuture<?> progressTask;
	private ScheduledFuture<?> eligibilityRefreshTask;
	private List<Object> registered;
	private volatile boolean featuresActive;
	private String firstConnectionSyncedAccount;
	private String activePlayerName;
	private final Runnable connectionListener = () -> clientThread.invokeLater(this::updateFeatureActivation);

	@Provides ZweetnekkenConfig provideConfig(ConfigManager manager) { return manager.getConfig(ZweetnekkenConfig.class); }

	@Provides Filepath providePluginDirectory() throws IOException { return getPluginDirectory(); }

	@Override protected void startUp()
	{
		panel.refreshBanner();
		navigation = NavigationButton.builder().tooltip("Zweetnekken").icon(loadIcon()).priority(5).panel(panel).build(); toolbar.addNavigation(navigation);
		overlayManager.add(eventAlertOverlay);
		overlayManager.add(bingoEventOverlay);
		registered = Arrays.asList(parties, loot, weaponCreation, collectionLog, pets, combatTiers, pbs);
		data.addListener(connectionListener);
		data.validate();
		executor.execute(() -> evidence.pruneUploaded(config.retentionDays()));
		if (client.getGameState() == GameState.LOGGED_IN) onLoggedIn();
		refreshTask = executor.scheduleAtFixedRate(this::runScheduledRefresh,
			PROFILE_AND_COMPETITIONS_REFRESH_MINUTES,
			PROFILE_AND_COMPETITIONS_REFRESH_MINUTES,
			TimeUnit.MINUTES);
		progressTask = executor.scheduleAtFixedRate(this::runScheduledProgressSync,
			PLAYER_PROGRESS_REFRESH_MINUTES,
			PLAYER_PROGRESS_REFRESH_MINUTES,
			TimeUnit.MINUTES);
		eligibilityRefreshTask = executor.scheduleAtFixedRate(this::runScheduledEligibilityRefresh,
			PLAYER_ELIGIBILITY_REFRESH_MINUTES,
			PLAYER_ELIGIBILITY_REFRESH_MINUTES,
			TimeUnit.MINUTES);
	}

	@Override protected void shutDown()
	{
		if (refreshTask != null) { refreshTask.cancel(false); refreshTask = null; }
		if (progressTask != null) { progressTask.cancel(false); progressTask = null; }
		if (eligibilityRefreshTask != null) { eligibilityRefreshTask.cancel(false); eligibilityRefreshTask = null; }
		deactivateFeatures();
		registered = null;
		data.removeListener(connectionListener);
		if (navigation != null) { toolbar.removeNavigation(navigation); navigation = null; }
		overlayManager.remove(eventAlertOverlay);
		overlayManager.remove(bingoEventOverlay);
		eventAlerts.resetStateForWorldHopOrLogin();
		bingo.clear();
		activePlayerName = null;
		firstConnectionSyncedAccount = null;
		data.loggedOut();
	}

	@Subscribe public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			eventAlerts.resetStateForLoginScreen();
		}
		else if (event.getGameState() == GameState.HOPPING
			|| event.getGameState() == GameState.CONNECTION_LOST)
		{
			eventAlerts.resetStateForWorldHopOrLogin();
		}
		if (event.getGameState() == GameState.LOGGED_IN) tryOnLoggedIn();
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			deactivateFeatures();
			activePlayerName = null;
			firstConnectionSyncedAccount = null;
			bingo.clear();
			data.loggedOut();
		}
	}

	@Subscribe public void onGameTick(GameTick event)
	{
		tryOnLoggedIn();
		if (config.eventAlerts()) eventAlerts.onGameTick();
	}

	@Subscribe public void onConfigChanged(ConfigChanged event)
	{
		if (!ZweetnekkenConfig.GROUP.equals(event.getGroup())) return;
		switch (event.getKey())
		{
			case "authenticationCode": firstConnectionSyncedAccount = null; data.validate(); updateFeatureActivation(); break;
			case "eventAlerts": eventAlerts.resetStateForConfigChange(); break;
			case "animatedBanner": panel.refreshBanner(); break;
			case "refreshProfile": if (Boolean.parseBoolean(event.getNewValue())) { refreshCurrentPlayer(); resetAction(event.getKey()); } break;
			case "retryOutbox": if (Boolean.parseBoolean(event.getNewValue())) { if (featuresActive) pipeline.retryAll(); resetAction(event.getKey()); } break;
			case "clearImageCache": if (Boolean.parseBoolean(event.getNewValue())) { panel.invalidateBannerLoads(); resetAction(event.getKey()); imageCache.clear(() -> clientThread.invokeLater(() -> { refreshCurrentPlayer(); panel.refreshBanner(); })); } break;
			default: break;
		}
	}

	/** Keeps legacy action config items usable without leaving a checked state behind. */
	private void resetAction(String key) { configManager.setConfiguration(ZweetnekkenConfig.GROUP, key, false); }

	private void onLoggedIn() { tryOnLoggedIn(); }
	private void tryOnLoggedIn()
	{
		if (client.getGameState() != GameState.LOGGED_IN) return;
		String name = currentName();
		if (name == null || name.isBlank()) return;
		if (name.equals(activePlayerName)) { updateFeatureActivation(); return; }
		activePlayerName = name;
		firstConnectionSyncedAccount = null;
		data.refresh(name);
		updateFeatureActivation();
	}

	private void updateFeatureActivation()
	{
		// Region loading can temporarily remove the local player. Preserve feature
		// subscriptions and raid state through that transition; login/hop still reset normally.
		if (client.getGameState() == GameState.LOADING) return;
		String name = currentName();
		if (client.getGameState() == GameState.LOGGED_IN && (name == null || name.isBlank())) return;
		boolean shouldBeActive = client.getGameState() == GameState.LOGGED_IN
			&& name != null && !name.isBlank()
			&& data.connection() == ZweetnekkenDataService.Connection.CONNECTED
			&& data.isCurrentPlayerPluginEligible();
		if (!shouldBeActive)
		{
			deactivateFeatures();
			return;
		}
		if (!featuresActive)
		{
			featuresActive = true;
			weaponCreation.reset();
			for (Object listener : registered) eventBus.register(listener);
			bingo.refresh();
			pbs.onLogin();
			pipeline.retryAll();
			pipeline.refreshStatuses(name);
		}
		syncFirstConnectionData();
	}

	private void deactivateFeatures()
	{
		if (!featuresActive) return;
		featuresActive = false;
		weaponCreation.reset();
		if (registered != null) for (Object listener : registered) eventBus.unregister(listener);
		firstConnectionSyncedAccount = null;
		eventAlerts.resetStateForWorldHopOrLogin();
		bingo.clear();
	}

	private void syncFirstConnectionData()
	{
		if (!featuresActive || !data.isCurrentPlayerPluginEligible()
			|| data.connection() != ZweetnekkenDataService.Connection.CONNECTED
			|| client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null) return;
		String account = Long.toString(client.getAccountHash());
		if ("0".equals(account)) return;
		if (account.equals(firstConnectionSyncedAccount)) return;
		firstConnectionSyncedAccount = account;
		clientThread.invokeLater(progress::syncAll);
		executor.execute(() -> pbs.syncAll(true));
	}
	private void refreshCurrentPlayer()
	{
		String name = currentName();
		if (name == null || name.isBlank()) return;
		data.refresh(name);
		if (featuresActive)
		{
			bingo.refresh();
			pipeline.refreshStatuses(name);
		}
	}
	private void runScheduledRefresh()
	{
		try { refreshCurrentPlayer(); }
		catch (RuntimeException e) { log.error("Unable to refresh Zweetnekken profile and competitions", e); }
	}
	private void runScheduledEligibilityRefresh()
	{
		if (client.getGameState() != GameState.LOGGED_IN) return;
		String name = currentName();
		if (name == null || name.isBlank()) return;
		try { data.refreshProfile(name); }
		catch (RuntimeException e) { log.error("Unable to refresh Zweetnekken plugin eligibility", e); }
	}

	private void runScheduledProgressSync()
	{
		if (!featuresActive) return;
		try { clientThread.invokeLater(progress::syncAll); }
		catch (RuntimeException e) { log.error("Unable to schedule Zweetnekken player progress sync", e); }
	}
	private String currentName() { return client.getLocalPlayer() == null ? null : client.getLocalPlayer().getName(); }

	private BufferedImage loadIcon()
	{
		BufferedImage image = new BufferedImage(32, 32, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(22, 31, 43));
		g.fillOval(1, 1, 30, 30);
		g.setColor(new Color(207, 164, 76));
		g.setFont(new java.awt.Font("SansSerif", java.awt.Font.BOLD, 22));
		g.drawString("Z", 7, 24);
		g.dispose();
		return image;
	}
}

/*
 * Portions adapted from the Llama Club and PB Tracker Sync HTTP clients.
 * See LICENSES/llama-LICENSE.txt and LICENSES/pb-tracker-sync-LICENSE.txt.
 */
package com.zweetnekken.api;

import com.google.gson.Gson;
import com.zweetnekken.ZweetnekkenConfig;
import com.zweetnekken.model.ZweetnekkenModels;
import com.zweetnekken.model.EventAlert;
import java.io.IOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.io.InputStream;
import net.runelite.client.util.Filepath;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Singleton
public class ZweetnekkenApiClient
{
	public static final String ZWEETNEKKEN_API_ORIGIN = "https://api-production-81001.up.railway.app";
	private static final Logger log = LoggerFactory.getLogger(ZweetnekkenApiClient.class);
	public static final String PLUGIN_VERSION = "1.1.42";
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private final OkHttpClient http;
	private final Gson gson;
	private final ZweetnekkenConfig config;
	private final String origin;
	private final ScheduledExecutorService executor;

	@Inject
	public ZweetnekkenApiClient(OkHttpClient http, Gson gson, ZweetnekkenConfig config, ScheduledExecutorService executor)
	{
		this(http, gson, config, ZWEETNEKKEN_API_ORIGIN, executor);
	}

	// Visible to package tests only; production requests use the Zweetnekken backend.
	ZweetnekkenApiClient(OkHttpClient http, Gson gson, ZweetnekkenConfig config, String origin)
	{
		this(http, gson, config, origin, null);
	}

	ZweetnekkenApiClient(OkHttpClient http, Gson gson, ZweetnekkenConfig config, String origin,
		ScheduledExecutorService executor)
	{
		this.http = http.newBuilder().followRedirects(false).followSslRedirects(false).build();
		this.gson = gson;
		this.config = config;
		this.origin = origin.replaceAll("/+$", "");
		this.executor = executor;
	}

	public interface ResultCallback<T> { void complete(ApiResult<T> result); }

	public static final class ApiResult<T>
	{
		public final int statusCode;
		public final T value;
		public final String error;
		private ApiResult(int statusCode, T value, String error) { this.statusCode = statusCode; this.value = value; this.error = error; }
		public static <T> ApiResult<T> ok(int code, T value) { return new ApiResult<>(code, value, null); }
		public static <T> ApiResult<T> error(int code, String error) { return new ApiResult<>(code, null, error); }
		public boolean isSuccessful() { return statusCode >= 200 && statusCode < 300; }
		public boolean isRetryable() { return statusCode == 0 || statusCode == 429 || statusCode >= 500; }
	}

	public void getProfile(String name, ResultCallback<ZweetnekkenModels.Profile> callback)
	{
		get("/api/clan/profile?name=" + encode(name), false, ZweetnekkenModels.Profile.class, callback);
	}

	public void getCompetitions(ResultCallback<ZweetnekkenModels.Competitions> callback)
	{
		get("/api/competitions", false, ZweetnekkenModels.Competitions.class, callback);
	}

	public void getCompetitionPanels(ResultCallback<ZweetnekkenModels.CompetitionPanels> callback)
	{
		get("/api/competitions/panels", false, ZweetnekkenModels.CompetitionPanels.class, callback);
	}

	public void validateSession(ResultCallback<Map> callback) { get("/api/runelite/session", true, Map.class, callback); }
	public void getRules(ResultCallback<ZweetnekkenModels.Rules> callback) { get("/api/runelite/rules", true, ZweetnekkenModels.Rules.class, callback); }
	public void getBingo(ResultCallback<ZweetnekkenModels.BingoEvent> callback)
	{
		get("/api/runelite/bingo", true, ZweetnekkenModels.BingoEvent.class, callback);
	}
	public void getBingoRules(ResultCallback<ZweetnekkenModels.BingoRules> callback)
	{
		get("/api/runelite/bingo/rules", true, ZweetnekkenModels.BingoRules.class, callback);
	}

	public void getEventAlert(ResultCallback<EventAlert> callback)
	{
		get("/api/runelite/event-alerts", false, EventAlert.class, callback);
	}

	public void uploadEvent(ZweetnekkenModels.EventEnvelope metadata, Filepath screenshot, String format,
		ResultCallback<ZweetnekkenModels.EventResponse> callback)
	{
		try
		{
			String metadataJson = gson.toJson(metadata);
			MultipartBody.Builder bodyBuilder = new MultipartBody.Builder().setType(MultipartBody.FORM)
				.addFormDataPart("metadata", null, RequestBody.create(JSON, metadataJson));
			if (screenshot != null)
			{
				byte[] screenshotBytes;
				try (InputStream input = screenshot.openInputStream())
				{
					screenshotBytes = input.readAllBytes();
				}
				MediaType imageType = MediaType.parse("image/" + ("jpg".equals(format) ? "jpeg" : format));
				bodyBuilder.addFormDataPart("screenshot", screenshot.getFileName(), RequestBody.create(imageType, screenshotBytes));
			}
			MultipartBody body = bodyBuilder.build();
			execute(newRequest("/api/runelite/events", true).post(body).build(),
				ZweetnekkenModels.EventResponse.class, callback);
		}
		catch (IOException e)
		{
			log.error("Could not read evidence screenshot {}", screenshot, e);
			callback.complete(ApiResult.error(0, "Could not read evidence screenshot"));
		}
	}

	public void syncPbs(ZweetnekkenModels.PbBulkRequest request, boolean bulk, ResultCallback<Map> callback)
	{
		postJson(bulk ? "/api/runelite/personal-bests/bulk" : "/api/runelite/personal-bests", request, Map.class, callback);
	}

	public void syncPlayerProgress(ZweetnekkenModels.PlayerProgressRequest request, ResultCallback<Map> callback)
	{
		Runnable send = () -> postJson("/api/runelite/player-progress", request, Map.class, callback);
		if (executor == null) send.run();
		else executor.execute(send);
	}

	public void syncCollectionLog(ZweetnekkenModels.CollectionLogRequest request, ResultCallback<Map> callback)
	{
		postJson("/api/runelite/collection-log", request, Map.class, callback);
	}

	public void updateSubmission(String id, int partySize, int clanMembers, int nonClanMembers,
		List<ZweetnekkenModels.PartyMember> partyMembers, String notes, ResultCallback<Map> callback)
	{
		postJsonWithMethod("/api/runelite/submissions/" + encode(id), Map.of("submittedPartySize", partySize,
			"submittedClanMemberCount", clanMembers, "submittedNonClanMemberCount", nonClanMembers,
			"submittedPartyMembers", partyMembers == null ? List.of() : partyMembers, "notes", notes),
			"PATCH", Map.class, callback);
	}

	public void submit(String id, ResultCallback<Map> callback)
	{
		postJson("/api/runelite/submissions/submit", Map.of("submissionId", id), Map.class, callback);
	}

	public void getSubmissions(String player, ResultCallback<ZweetnekkenModels.SubmissionSummary[]> callback)
	{
		get("/api/runelite/submissions?player=" + encode(player), true, ZweetnekkenModels.SubmissionSummary[].class, callback);
	}

	private <T> void get(String path, boolean authenticated, Class<T> type, ResultCallback<T> callback)
	{
		execute(newRequest(path, authenticated).get().build(), type, callback);
	}

	private <T> void postJson(String path, Object value, Class<T> type, ResultCallback<T> callback)
	{
		postJsonWithMethod(path, value, "POST", type, callback);
	}

	private <T> void postJsonWithMethod(String path, Object value, String method, Class<T> type, ResultCallback<T> callback)
	{
		String json = gson.toJson(value);
		if ("/api/runelite/player-progress".equals(path))
		{
			if (json.contains("\"name\":null") || json.contains("\"name\":\"\""))
			{
				log.error("Player-progress payload contains a null or blank name before POST");
			}
		}
		RequestBody body = RequestBody.create(JSON, json);
		execute(newRequest(path, true).method(method, body).build(), type, callback);
	}

	private Request.Builder newRequest(String path, boolean authenticated)
	{
		Request.Builder builder = new Request.Builder().url(baseUrl() + path)
			.header("Accept", "application/json")
			.header("X-Zweetnekken-Plugin-Version", PLUGIN_VERSION);
		if (authenticated)
		{
			String code = config.authenticationCode() == null ? "" : config.authenticationCode().trim();
			if (!code.isEmpty()) { builder.header("Authorization", "Bearer " + code); }
		}
		return builder;
	}

	private <T> void execute(Request request, Class<T> type, ResultCallback<T> callback)
	{
		http.newCall(request).enqueue(new Callback()
		{
			@Override public void onFailure(Call call, IOException e)
			{
				log.error("Zweetnekken API request failed: {} {}", request.method(), request.url().encodedPath(), e);
				callback.complete(ApiResult.error(0, "Network unavailable"));
			}
			@Override public void onResponse(Call call, Response response)
			{
				String body = "";
				try (Response ignored = response)
				{
					body = response.body() == null ? "" : response.body().string();
					if (!response.isSuccessful() && response.code() != 409)
					{
						log.error("Zweetnekken API returned HTTP {} for {} {}: {}", response.code(), request.method(),
							request.url().encodedPath(), responsePreview(body));
						callback.complete(ApiResult.error(response.code(), safeError(response.code())));
						return;
					}
					T parsed = body.isBlank() ? null : gson.fromJson(body, type);
					callback.complete(ApiResult.ok(response.code() == 409 ? 200 : response.code(), parsed));
				}
				catch (IOException | RuntimeException e)
				{
					log.error("Invalid Zweetnekken API response for {} {} (HTTP {}, content-type {}): {}", request.method(),
						request.url().encodedPath(), response.code(), response.header("Content-Type"), responsePreview(body), e);
					callback.complete(ApiResult.error(0, "Invalid server response"));
				}
			}
		});
	}

	private String responsePreview(String body)
	{
		if (body == null || body.isBlank()) return "<empty body>";
		String safe = body.replace('\r', ' ').replace('\n', ' ');
		String code = config.authenticationCode() == null ? "" : config.authenticationCode().trim();
		if (!code.isEmpty()) safe = safe.replace(code, "[redacted]");
		return safe.length() <= 2_000 ? safe : safe.substring(0, 2_000) + "… [truncated]";
	}

	private String baseUrl()
	{
		return origin;
	}

	private static String encode(String value) { return URLEncoder.encode(value == null ? "" : value, StandardCharsets.UTF_8).replace("+", "%20"); }
	private static String safeError(int status)
	{
		if (status == 401 || status == 403) return "Authentication code is invalid";
		if (status == 422) return "The server rejected this draft";
		if (status == 429) return "The server is busy; retry queued";
		return status >= 500 ? "Zweetnekken is temporarily unavailable" : "Request failed (HTTP " + status + ")";
	}
}

package com.zweetnekken.collection;

import com.zweetnekken.ZweetnekkenConfig;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;

@Singleton
public class CollectionLogPromptState
{
	private static final String KEY_PREFIX = "collectionLogSynced.";
	private final Client client;
	private final ConfigManager configManager;

	@Inject
	public CollectionLogPromptState(Client client, ConfigManager configManager)
	{
		this.client = client;
		this.configManager = configManager;
	}

	public boolean hasSyncedForCurrentAccount()
	{
		String key = currentAccountKey();
		return key != null && Boolean.parseBoolean(configManager.getConfiguration(ZweetnekkenConfig.GROUP, key));
	}

	public boolean markSyncedForCurrentAccount()
	{
		return markSyncedForAccount(Long.toString(client.getAccountHash()));
	}

	public boolean markSyncedForAccount(String accountHash)
	{
		String key = accountKey(accountHash);
		if (key == null)
		{
			return false;
		}
		if (!Boolean.parseBoolean(configManager.getConfiguration(ZweetnekkenConfig.GROUP, key)))
		{
			configManager.setConfiguration(ZweetnekkenConfig.GROUP, key, true);
		}
		return true;
	}

	private String currentAccountKey()
	{
		return accountKey(Long.toString(client.getAccountHash()));
	}

	private static String accountKey(String accountHash)
	{
		return accountHash == null || accountHash.isBlank() || "0".equals(accountHash) ? null : KEY_PREFIX + accountHash;
	}

}

/*
 * Portions adapted from the Terpinheimer collection-log synchronization code.
 * The item capture also follows RuneProfile's WikiSync-derived script 4100 flow.
 * See LICENSES/terpinheimer-LICENSE.txt and LICENSES/reference-plugins.txt.
 */
package com.zweetnekken.collection;

import com.google.gson.Gson;
import com.zweetnekken.ZweetnekkenConfig;
import com.zweetnekken.api.ZweetnekkenApiClient;
import com.zweetnekken.model.ZweetnekkenModels;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.ItemComposition;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

@Slf4j
@Singleton
public class CollectionLogSyncService
{
	static final int COLLECTION_ITEM_SCRIPT = 4100;
	private static final String PENDING_PREFIX = "collectionLogPending.";

	private final Client client;
	private final ConfigManager configManager;
	private final Gson gson;
	private final ZweetnekkenApiClient api;
	private final CollectionLogPromptState promptState;
	private final ItemManager itemManager;
	private final ScheduledExecutorService executor;
	private final Map<Integer, Integer> items = new LinkedHashMap<>();
	private int lastItemScriptTick = -1;
	private volatile String lastSuccessfulAccountHash;

	@Inject
	public CollectionLogSyncService(Client client, ConfigManager configManager, Gson gson, ZweetnekkenApiClient api,
		CollectionLogPromptState promptState, ItemManager itemManager, ScheduledExecutorService executor)
	{
		this.client = client;
		this.configManager = configManager;
		this.gson = gson;
		this.api = api;
		this.promptState = promptState;
		this.itemManager = itemManager;
		this.executor = executor;
	}

	/** Keeps the lightweight unit-test constructor while production uses the executor. */
	public CollectionLogSyncService(Client client, ConfigManager configManager, Gson gson, ZweetnekkenApiClient api,
		CollectionLogPromptState promptState, ItemManager itemManager)
	{
		this(client, configManager, gson, api, promptState, itemManager, null);
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != COLLECTION_ITEM_SCRIPT
			|| client.getGameState() != GameState.LOGGED_IN
			|| client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1)
		{
			return;
		}
		Object[] args = event.getScriptEvent().getArguments();
		if (args == null || args.length < 3 || !(args[1] instanceof Number) || !(args[2] instanceof Number)) return;
		int itemId = ((Number) args[1]).intValue();
		int quantity = ((Number) args[2]).intValue();
		if (itemId <= 0 || quantity <= 0) return;
		synchronized (items) { items.put(itemId, quantity); }
		lastItemScriptTick = client.getTickCount();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.HOPPING && event.getGameState() != GameState.LOGGED_IN)
		{
			synchronized (items) { items.clear(); }
			lastItemScriptTick = -1;
		}
	}

	/** Called after the open collection log has finished populating its item rows. */
	public boolean syncCapturedItems()
	{
		return syncCapturedItems(success -> { });
	}

	/** Starts a sync and reports whether the server accepted it. */
	public boolean syncCapturedItems(Consumer<Boolean> completion)
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null
			|| client.getAccountHash() == 0L)
		{
			return false;
		}
		Map<Integer, Integer> captured;
		synchronized (items) { captured = new LinkedHashMap<>(items); }
		if (lastItemScriptTick != -1 && lastItemScriptTick + 2 >= client.getTickCount())
		{
			return false;
		}
		if (captured.isEmpty())
		{
			log.error("Collection log sync requested before script {} produced any item rows; lastRowTick={}, currentTick={}",
				COLLECTION_ITEM_SCRIPT, lastItemScriptTick, client.getTickCount());
			return false;
		}
		// Capture only the small client-thread-safe metadata here. A full collection
		// log can contain thousands of rows, so request assembly and serialisation are
		// deliberately deferred to the worker executor.
		ZweetnekkenModels.CollectionLogRequest request = collectMetadata();
		Runnable persistAndSend = () ->
		{
			addCapturedItems(request, captured, false);
			configManager.setConfiguration(ZweetnekkenConfig.GROUP, pendingKeyFor(request), gson.toJson(request));
			send(request, completion);
		};
		if (executor == null) persistAndSend.run();
		else executor.execute(persistAndSend);
		return true;
	}

	/** True once this opening of the collection log has produced and settled its item rows. */
	public boolean isCaptureReadySince(int openedAtTick)
	{
		if (client.getGameState() != GameState.LOGGED_IN || lastItemScriptTick < openedAtTick - 1
			|| lastItemScriptTick + 2 >= client.getTickCount()) return false;
		synchronized (items) { return !items.isEmpty(); }
	}

	public boolean hasCapturedItems()
	{
		synchronized (items) { return !items.isEmpty(); }
	}

	public boolean hasSyncedCurrentAccount()
	{
		return Long.toString(client.getAccountHash()).equals(lastSuccessfulAccountHash)
			|| promptState.hasSyncedForCurrentAccount();
	}

	public void retryPending()
	{
		String key = pendingKey();
		if (key == null) return;
		Runnable retry = () -> retryPending(key);
		if (executor == null) retry.run();
		else executor.execute(retry);
	}

	private void retryPending(String key)
	{
		String json = configManager.getConfiguration(ZweetnekkenConfig.GROUP, key);
		if (json == null || json.isBlank()) return;
		try
		{
			ZweetnekkenModels.CollectionLogRequest request = gson.fromJson(json, ZweetnekkenModels.CollectionLogRequest.class);
			if (request == null || request.syncId == null || request.items == null || request.items.isEmpty())
			{
				configManager.unsetConfiguration(ZweetnekkenConfig.GROUP, key);
				return;
			}
			send(request, success -> { });
		}
		catch (RuntimeException e)
		{
			configManager.unsetConfiguration(ZweetnekkenConfig.GROUP, key);
			log.error("Discarded unreadable pending collection log snapshot", e);
		}
	}

	ZweetnekkenModels.CollectionLogRequest collect(Map<Integer, Integer> captured)
	{
		ZweetnekkenModels.CollectionLogRequest request = collectMetadata();
		addCapturedItems(request, captured, true);
		return request;
	}

	private ZweetnekkenModels.CollectionLogRequest collectMetadata()
	{
		ZweetnekkenModels.CollectionLogRequest request = new ZweetnekkenModels.CollectionLogRequest();
		request.syncId = UUID.randomUUID().toString();
		request.capturedAt = Instant.now().toString();
		request.player = new ZweetnekkenModels.PlayerIdentity();
		request.player.name = client.getLocalPlayer().getName();
		request.player.accountHash = Long.toString(client.getAccountHash());
		request.obtainedCount = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
		request.totalCount = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
		addCategory(request, "bosses", VarPlayerID.COLLECTION_COUNT_BOSSES, VarPlayerID.COLLECTION_COUNT_BOSSES_MAX);
		addCategory(request, "raids", VarPlayerID.COLLECTION_COUNT_RAIDS, VarPlayerID.COLLECTION_COUNT_RAIDS_MAX);
		addCategory(request, "clues", VarPlayerID.COLLECTION_COUNT_CLUES, VarPlayerID.COLLECTION_COUNT_CLUES_MAX);
		addCategory(request, "minigames", VarPlayerID.COLLECTION_COUNT_MINIGAMES, VarPlayerID.COLLECTION_COUNT_MINIGAMES_MAX);
		addCategory(request, "other", VarPlayerID.COLLECTION_COUNT_OTHER, VarPlayerID.COLLECTION_COUNT_OTHER_MAX);
		return request;
	}

	private void addCapturedItems(ZweetnekkenModels.CollectionLogRequest request, Map<Integer, Integer> captured,
		boolean includeNames)
	{
		if (captured != null)
		{
			for (Map.Entry<Integer, Integer> entry : captured.entrySet())
			{
				String itemId = String.valueOf(entry.getKey());
				request.items.put(itemId, entry.getValue());
				if (includeNames) request.itemNames.put(itemId, resolveItemName(entry.getKey()));
			}
		}
	}

	private String pendingKeyFor(ZweetnekkenModels.CollectionLogRequest request)
	{
		return request == null || request.player == null || request.player.accountHash == null
			? pendingKey() : PENDING_PREFIX + request.player.accountHash;
	}

	private String resolveItemName(int itemId)
	{
		if (itemManager != null)
		{
			try
			{
				ItemComposition comp = itemManager.getItemComposition(itemId);
				if (comp != null && comp.getName() != null && !comp.getName().isEmpty() && !"null".equalsIgnoreCase(comp.getName()))
				{
					return comp.getName();
				}
			}
			catch (Exception e)
			{
				log.error("Failed to resolve item name for item ID {}", itemId, e);
			}
		}
		return String.valueOf(itemId);
	}

	private void addCategory(ZweetnekkenModels.CollectionLogRequest request, String name, int obtainedVarp, int totalVarp)
	{
		ZweetnekkenModels.CollectionCategoryProgress progress = new ZweetnekkenModels.CollectionCategoryProgress();
		progress.obtained = client.getVarpValue(obtainedVarp);
		progress.total = client.getVarpValue(totalVarp);
		request.categories.put(name, progress);
	}

	private void send(ZweetnekkenModels.CollectionLogRequest request, Consumer<Boolean> completion)
	{
		api.syncCollectionLog(request, result ->
		{
			if (result.isSuccessful())
			{
				lastSuccessfulAccountHash = request.player.accountHash;
				promptState.markSyncedForAccount(request.player.accountHash);
				configManager.unsetConfiguration(ZweetnekkenConfig.GROUP, PENDING_PREFIX + request.player.accountHash);
			}
			else
			{
				log.error("Collection log sync failed and remains queued: player={}, syncId={}, error={}",
					request.player.name, request.syncId, result.error);
			}
			completion.accept(result.isSuccessful());
		});
	}

	private String pendingKey()
	{
		long hash = client.getAccountHash();
		return hash == 0L ? null : PENDING_PREFIX + hash;
	}
}

/*
 * Portions adapted from the Llama Club and Terpinheimer collection-log notifiers.
 * See LICENSES/llama-LICENSE.txt and LICENSES/terpinheimer-LICENSE.txt.
 */
package com.zweetnekken.events;

import com.zweetnekken.evidence.EventPipeline;
import com.zweetnekken.evidence.EventDeduplicator;
import com.zweetnekken.model.ZweetnekkenModels;
import com.zweetnekken.service.RulesService;
import com.zweetnekken.service.BingoService;
import com.zweetnekken.service.PartyTracker;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.ItemComposition;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.Text;
import net.runelite.http.api.item.ItemPrice;

@Singleton
public class CollectionLogEventListener
{
	private static final Pattern PATTERN = Pattern.compile("New item added to your collection log: (.+)", Pattern.CASE_INSENSITIVE);
	@Inject private EventPipeline pipeline;
	@Inject private Client client;
	@Inject private ItemManager itemManager;
	@Inject private RulesService rules;
	@Inject private BingoService bingo;
	@Inject private PartyTracker parties;
	@Inject private ScheduledExecutorService executor;
	@Inject private ClientThread clientThread;
	private final AtomicBoolean popupStarted = new AtomicBoolean();
	/** Chat and popup notifications for one unlock can be separated by several seconds. */
	private final EventDeduplicator notificationDeduplicator = new EventDeduplicator(30_000L);

	@Subscribe public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM) return;
		Matcher matcher = PATTERN.matcher(Text.removeTags(event.getMessage())); if (!matcher.find()) return;
		scheduleCapture(normalizeItemName(matcher.group(1)), "chat");
	}

	@Subscribe public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.NOTIFICATION_START) { popupStarted.set(true); return; }
		if (event.getScriptId() != ScriptID.NOTIFICATION_DELAY || !popupStarted.getAndSet(false)) return;
		String title = client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE);
		String body = client.getVarcStrValue(VarClientID.NOTIFICATION_MAIN);
		if (!"Collection log".equalsIgnoreCase(title) || body == null) return;
		String item = normalizeItemName(body).replaceFirst("(?i)^New item:\\s*", "").trim();
		if (item.isEmpty()) return;
		scheduleCapture(item, "popup");
	}

	private void scheduleCapture(String itemName, String detectionSource)
	{
		if (itemName.isEmpty()) return;
		// RuneLite can publish the collection-log message before its raid LootReceived event.
		// Waiting one game tick lets that event establish the real encounter category and win
		// loot deduplication while the collection-log notification is still visible.
		executor.schedule(() -> clientThread.invokeLater(() -> capture(itemName, detectionSource)), 600, TimeUnit.MILLISECONDS);
	}

	private void capture(String itemName, String detectionSource)
	{
		if (!acceptNotification(itemName, System.currentTimeMillis())) return;
		List<ZweetnekkenModels.Item> items = collectionLogItems(itemName);
		HashMap<String, Object> details = new HashMap<>();
		details.put("itemName", itemName);
		details.put("detectionSource", detectionSource);
		details.put("autoSubmit", true);
		String dedupeKey = itemName.toLowerCase(java.util.Locale.ROOT);
		ZweetnekkenModels.Source source = parties.resolveCollectionLogSource(collectionLogSource());
		for (String eventType : eventTypesFor(items, rules.current()))
			pipeline.capture(eventType, dedupeKey, source, items, details, "loot".equals(eventType));
		if (bingo.shouldCaptureCollectionLog(items))
		{
			HashMap<String, Object> bingoDetails = new HashMap<>(details);
			bingo.decorateDetails(bingoDetails);
			pipeline.capture(bingo.eventType(), dedupeKey, source, items, bingoDetails, true,
				bingo.rulesVersion(), bingo.screenshotRequired(), bingo.finalizeSubmission());
		}
	}

	static List<String> eventTypesFor(List<ZweetnekkenModels.Item> items, ZweetnekkenModels.Rules rules)
	{
		// LootEventListener owns the actual clue/boss loot event. A collection-log
		// notification is a separate unlock signal and must not manufacture a
		// second loot envelope for the same drop.
		return Collections.singletonList("collection_log");
	}

	boolean acceptNotification(String itemName, long now)
	{
		if (itemName == null || itemName.isEmpty()) return false;
		return notificationDeduplicator.accept(itemName.toLowerCase(java.util.Locale.ROOT), now);
	}

	static String normalizeItemName(String value)
	{
		return value == null ? "" : Text.removeTags(value).trim();
	}

	static ZweetnekkenModels.Source collectionLogSource()
	{
		ZweetnekkenModels.Source source = new ZweetnekkenModels.Source();
		source.type = "collection_log";
		source.name = "Collection Log";
		return source;
	}

	private List<ZweetnekkenModels.Item> collectionLogItems(String itemName)
	{
		try
		{
			int itemId = 0;
			List<ItemPrice> matches = itemManager != null ? itemManager.search(itemName) : null;
			if (matches != null && !matches.isEmpty())
			{
				itemId = matches.get(0).getId();
				for (ItemPrice match : matches)
				{
					ItemComposition composition = itemManager.getItemComposition(match.getId());
					if (composition != null && itemName.equalsIgnoreCase(composition.getName())) { itemId = match.getId(); break; }
				}
			}

			ZweetnekkenModels.Item item = new ZweetnekkenModels.Item();
			item.itemId = itemId;
			item.name = itemName;
			item.quantity = 1;

			if (itemId > 0 && itemManager != null)
			{
				long price = itemManager.getItemPrice(itemId);
				if (price <= 0)
				{
					try { price = itemManager.getItemPriceWithSource(itemId, true); } catch (Throwable ignored) {}
				}
				item.unitGeValue = price;
				item.totalGeValue = price;
				ItemComposition composition = itemManager.getItemComposition(itemId);
				if (composition != null) { item.tradeable = composition.isTradeable(); item.stackable = composition.isStackable(); }
			}

			return Collections.singletonList(item);
		}
		catch (RuntimeException ignored)
		{
			ZweetnekkenModels.Item fallback = new ZweetnekkenModels.Item();
			fallback.name = itemName;
			fallback.quantity = 1;
			return Collections.singletonList(fallback);
		}
	}
}

