		"thermonuclear smoke devil", "tombs of amascut", "tombs of amascut expert mode", "tzkal zuk",
		"tztok jad", "vardorvis", "venenatis", "vetion", "vorkath", "wintertodt", "yama", "zalcano", "zulrah"
	);

	private static final Map<String, String> ALIASES = Map.ofEntries(
		Map.entry("fractured archive", "the fractured archive"),
		Map.entry("barrows", "barrows chests"), Map.entry("lunar chest", "lunar chests"),
		Map.entry("the mimic", "mimic"), Map.entry("the nightmare", "nightmare"),
		Map.entry("dusk", "grotesque guardians"), Map.entry("dawn", "grotesque guardians"),
		Map.entry("crystalline hunllef", "the gauntlet"),
		Map.entry("corrupted hunllef", "the corrupted gauntlet"),
		Map.entry("gauntlet", "the gauntlet"), Map.entry("corrupted gauntlet", "the corrupted gauntlet"),
		Map.entry("hueycoatl", "the hueycoatl"), Map.entry("leviathan", "the leviathan"),
		Map.entry("royal titans", "the royal titans"), Map.entry("whisperer", "the whisperer"),
		Map.entry("branda the fire queen", "the royal titans"),
		Map.entry("eldric the ice king", "the royal titans"),
		Map.entry("chambers of xeric cm", "chambers of xeric challenge mode"),
		Map.entry("theatre of blood entry mode", "theatre of blood"),
		Map.entry("tombs of amascut entry mode", "tombs of amascut"),
		Map.entry("fortis colosseum", "sol heredit")
	);

	private BossRegistry() { }

	public static boolean isSupported(String source) { return SUPPORTED.contains(normalize(source)); }
	public static boolean canBeMulti(String source) { return MULTI.contains(normalize(source)); }
	public static boolean isRaid(String source)
	{
		String value = normalize(source);
		return value.startsWith("chambers of xeric") || value.startsWith("theatre of blood")
			|| value.startsWith("tombs of amascut") || value.equals("the fractured archive");
	}

	static String normalize(String source)
	{
		if (source == null) return "";
		String value = source.toLowerCase(Locale.ROOT).replace('\u2019', '\'').replace("'", "")
			.replace(':', ' ').replace('-', ' ').trim().replaceAll("\\s+", " ");
		return ALIASES.getOrDefault(value, value);
	}
}

/*
 * Competition ranking logic adapted from the Terpinheimer competition code.
 * See LICENSES/terpinheimer-LICENSE.txt.
 */
package com.zweetnekken.service;

import com.zweetnekken.model.ZweetnekkenModels;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;

public final class CompetitionService
{
	private CompetitionService() {}

	public static List<Leader> leaders(ZweetnekkenModels.Competition competition, int limit)
	{
		List<Leader> result = new ArrayList<>();
		if (competition == null || competition.topHistory == null) return result;
		for (ZweetnekkenModels.TopHistory entry : competition.topHistory)
		{
			if (entry == null || entry.player == null || entry.history == null || entry.history.isEmpty()) continue;
			long value = entry.history.get(entry.history.size() - 1).value;
			String name = entry.player.displayName == null ? entry.player.username : entry.player.displayName;
			result.add(new Leader(name == null ? "Unknown" : name, Math.max(0, value)));
		}
		result.sort(Comparator.comparingLong(Leader::getValue).reversed().thenComparing(Leader::getName, String.CASE_INSENSITIVE_ORDER));
		return result.subList(0, Math.min(limit, result.size()));
	}

	public static ZweetnekkenModels.CompetitionPanel convertToPanel(ZweetnekkenModels.Competition comp, String kind)
	{
		if (comp == null) return null;
		ZweetnekkenModels.CompetitionPanel panel = new ZweetnekkenModels.CompetitionPanel();
		panel.competitionId = comp.id;
		panel.kind = kind;
		panel.title = comp.title;
		panel.metric = comp.metric;
		boolean isKillCount = "BOTW".equalsIgnoreCase(kind);
		if (isKillCount)
		{
			panel.metricLabel = comp.bossName != null && !comp.bossName.isBlank() ? comp.bossName : formatMetricLabel(comp.metric);
			panel.unit = "KC";
		}
		else
		{
			panel.metricLabel = comp.skillName != null && !comp.skillName.isBlank() ? comp.skillName : formatMetricLabel(comp.metric);
			panel.unit = "XP";
		}
		panel.startsAt = comp.startsAt;
		panel.endsAt = comp.endsAt;
		panel.participantCount = comp.participantCount;
		panel.status = comp.status != null && !comp.status.isBlank() ? comp.status : inferredStatus(comp);
		List<Leader> leaders = leaders(comp, 10);
		for (int i = 0; i < leaders.size(); i++)
		{
			Leader l = leaders.get(i);
			ZweetnekkenModels.PanelLeader leader = new ZweetnekkenModels.PanelLeader();
			leader.rank = i + 1;
			leader.username = l.getName();
			leader.displayName = l.getName();
			leader.gained = l.getValue();
			leader.unit = panel.unit;
			leader.displayValue = String.format("%,d %s", l.getValue(), panel.unit);
			panel.leaders.add(leader);
		}
		return panel;
	}


	private static String inferredStatus(ZweetnekkenModels.Competition competition)
	{
		Instant now = Instant.now();
		try
		{
			if (competition.startsAt != null && !competition.startsAt.isBlank()
				&& Instant.parse(competition.startsAt).isAfter(now)) return "upcoming";
			if (competition.endsAt != null && !competition.endsAt.isBlank()
				&& Instant.parse(competition.endsAt).isBefore(now)) return "finished";
		}
		catch (RuntimeException ignored) { }
		return "active";
	}

	public static String formatMetricLabel(String metric)
	{
		if (metric == null || metric.isBlank()) return "";
		String[] words = metric.replace('_', ' ').split("\\s+");
		StringBuilder sb = new StringBuilder();
		for (String word : words)
		{
			if (word.isEmpty()) continue;
			if (sb.length() > 0) sb.append(' ');
			sb.append(Character.toUpperCase(word.charAt(0))).append(word.substring(1).toLowerCase(java.util.Locale.ROOT));
		}
		return sb.toString();
	}

	public static final class Leader
	{
		private final String name;
		private final long value;
		public Leader(String name, long value) { this.name = name; this.value = value; }
		public String getName() { return name; }
		public long getValue() { return value; }
		public long getGain() { return value; }
	}
}

/*
 * Event-alert polling and baseline behavior adapted from Odablock Sounds.
 * See LICENSES/odablock-sounds-LICENSE.txt.
 */
package com.zweetnekken.service;

import com.zweetnekken.ZweetnekkenConfig;
import com.zweetnekken.model.EventAlert;
import com.zweetnekken.api.ZweetnekkenApiClient;
import java.time.Instant;
import java.time.OffsetDateTime;
import java.time.format.DateTimeParseException;
import java.util.Collections;
import java.util.Iterator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;

@Slf4j
@Singleton
public class EventAlertService
{
	static final int POLL_INTERVAL_TICKS = 10;
	static final long OVERLAY_DURATION_MILLIS = 15_000L;
	private static final int MAX_SEEN_ALERT_KEYS = 300;

	private final Client client;
	private final ZweetnekkenApiClient api;
	private final ChatMessageManager chat;
	private final ZweetnekkenConfig config;
	private final ScheduledExecutorService executor;
	private final AtomicBoolean requestInFlight = new AtomicBoolean();
	private final Object stateLock = new Object();
	private final Set<String> seenAlertKeys = new LinkedHashSet<>();
	private Instant observationStartedAt = Instant.now();
	private volatile long serverClockOffsetMillis;
	private volatile boolean serverClockOffsetKnown;
	private int lastCheckedTick = -1;
	private int generation;
	private volatile String overlayMessage;
	private volatile long overlayExpiresAt;

	@Inject
	public EventAlertService(Client client, ZweetnekkenApiClient api,
		ChatMessageManager chat, ZweetnekkenConfig config, ScheduledExecutorService executor)
	{
		this.client = client;
		this.api = api;
		this.chat = chat;
		this.config = config;
		this.executor = executor;
	}

	public void onGameTick()
	{
		if (!config.eventAlerts()) return;
		int currentTick = client.getTickCount();
		if (lastCheckedTick != -1 && currentTick >= lastCheckedTick
			&& currentTick - lastCheckedTick <= POLL_INTERVAL_TICKS) return;
		if (!requestInFlight.compareAndSet(false, true)) return;
		lastCheckedTick = currentTick;
		final int requestGeneration;
		synchronized (stateLock) { requestGeneration = generation; }
		try
		{
			executor.execute(() -> requestAlert(requestGeneration));
		}
		catch (RuntimeException e)
		{
			requestInFlight.set(false);
			log.error("Unable to schedule Zweetnekken event-alert request", e);
		}
	}

	public void resetStateForWorldHopOrLogin()
	{
		resetState(false);
	}

	public void resetStateForLoginScreen()
	{
		resetState(true);
	}

	public void resetStateForConfigChange()
	{
		resetState(true);
	}

	private void resetState(boolean resetObservationWindow)
	{
		lastCheckedTick = -1;
		synchronized (stateLock)
		{
			generation++;
			if (resetObservationWindow)
			{
				observationStartedAt = Instant.now();
			}
		}
		clearOverlay();
	}

	public String activeOverlayMessage()
	{
		if (System.currentTimeMillis() >= overlayExpiresAt)
		{
			clearOverlay();
			return null;
		}
		return overlayMessage;
	}

	private void requestAlert(int requestGeneration)
	{
		api.getEventAlert(result ->
		{
			try
			{
				if (!result.isSuccessful())
				{
					log.warn("Zweetnekken event-alert API request failed: HTTP {}, {}",
						result.statusCode, result.error);
					return;
				}
				updateServerClockOffset(result.value == null ? null : result.value.getServerTime());
				acceptAlert(result.value, requestGeneration);
			}
			finally
			{
				requestInFlight.set(false);
			}
		});
	}

	void acceptAlert(EventAlert alert)
	{
		final int currentGeneration;
		synchronized (stateLock) { currentGeneration = generation; }
		acceptAlert(alert, currentGeneration);
	}

	private void acceptAlert(EventAlert alert, int requestGeneration)
	{
		List<EventAlert> alerts = alert == null ? null : alert.getHistory();
		log.debug("Received RuneLite event-alert response: currentMessagePresent={}, historyCount={}, serverTimePresent={}",
			alert != null && alert.getMessage() != null && !alert.getMessage().trim().isEmpty(),
			alerts == null ? 0 : alerts.size(),
			alert != null && alert.getServerTime() != null && !alert.getServerTime().trim().isEmpty());
		if (alerts == null || alerts.isEmpty())
		{
			// Backward compatibility with an API payload that only contains message/time.
			if (alert == null || alert.getMessage() == null || alert.getMessage().trim().isEmpty())
			{
				return;
			}
			alerts = Collections.singletonList(alert);
		}

		for (EventAlert published : alerts)
		{
			if (published == null || published.getMessage() == null || published.getMessage().trim().isEmpty())
			{
				continue;
			}
			String message = published.getMessage().trim();
			String key = alertKey(published, message);
			boolean shouldSend;
			synchronized (stateLock)
			{
				if (requestGeneration != generation)
				{
					return;
				}
				if (!seenAlertKeys.add(key))
				{
					continue;
				}
				while (seenAlertKeys.size() > MAX_SEEN_ALERT_KEYS)
				{
					Iterator<String> iterator = seenAlertKeys.iterator();
					iterator.next();
					iterator.remove();
				}
				shouldSend = wasPublishedAfterStartup(published.getTime());
			}
			if (!shouldSend)
			{
				continue;
			}

			log.info("Delivering Zweetnekken event alert: {}", message);
			sendChatMessage(message);
			overlayMessage = message;
			overlayExpiresAt = System.currentTimeMillis() + Math.max(1, config.eventAlertDuration()) * 1000L;
		}
	}

	private String alertKey(EventAlert alert, String message)
	{
		String time = alert.getTime();
		return (time == null || time.trim().isEmpty() ? "message" : time.trim()) + "|" + message;
	}

	private void updateServerClockOffset(String serverTime)
	{
		if (serverTime == null || serverTime.trim().isEmpty()) return;
		try
		{
			long offset = BackendClockTimestampParser.parse(serverTime).toEpochMilli() - System.currentTimeMillis();
			serverClockOffsetMillis = offset;
			serverClockOffsetKnown = true;
		}
		catch (DateTimeParseException e)
		{
			log.warn("Ignoring invalid Zweetnekken backend clock timestamp: {}", serverTime);
		}
	}

	private boolean wasPublishedAfterStartup(String time)
	{
		if (time == null || time.trim().isEmpty())
		{
			log.warn("RuneLite event alert has no timestamp; displaying it rather than hiding it.");
			return true;
		}
		try
		{
			Instant publishedAt = OffsetDateTime.parse(time.trim()).toInstant();
			Instant cutoff = observationStartedAt.minusSeconds(2);
			if (serverClockOffsetKnown)
			{
				cutoff = cutoff.plusMillis(serverClockOffsetMillis);
			}
			return !publishedAt.isBefore(cutoff);
		}
		catch (DateTimeParseException e)
		{
			log.warn("RuneLite event alert timestamp could not be parsed; displaying alert to avoid dropping it: {}", time);
			return true;
		}
	}

	private void sendChatMessage(String alert)
	{
		String formatted = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append("Zweetnekken Event Alert ~ ")
			.append(alert)
			.build();
		String color = String.format("%06x", config.eventAlertColor().getRGB() & 0xffffff);
		chat.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(formatted.replace("colHIGHLIGHT", "col=" + color))
			.build());
	}

	private void clearOverlay()
	{
		overlayMessage = null;
		overlayExpiresAt = 0L;
	}
}

/*
 * Portions adapted from the Terpinheimer remote-image loading code.
 * See LICENSES/terpinheimer-LICENSE.txt.
 */
package com.zweetnekken.service;

import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import net.runelite.client.util.Filepath;
import java.nio.file.StandardCopyOption;
import java.time.Duration;
import java.util.Locale;
import java.util.Iterator;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.stream.ImageInputStream;
import javax.swing.ImageIcon;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class ImageCache
{
	private static final long PROFILE_TTL = Duration.ofHours(24).toMillis();
	private final Filepath root;
	private final OkHttpClient http;
	private final ScheduledExecutorService executor;

	@Inject
	public ImageCache(OkHttpClient http, ScheduledExecutorService executor, Filepath pluginDirectory)
	{
		this.http = http.newBuilder().followRedirects(false).followSslRedirects(false).build();
		this.executor = executor;
		this.root = pluginDirectory.joinSegment("cache");
	}

	public void loadProfile(String rsn, String url, Consumer<BufferedImage> callback)
	{
		String urlKey = url == null ? "none" : Integer.toHexString(url.hashCode());
		load(root.join("profiles", safeName(rsn) + "-" + urlKey + ".img"), url, PROFILE_TTL, false, callback);
	}

	public void loadWebsiteImage(String key, String url, Consumer<BufferedImage> callback)
	{
		load(root.join("website-images", safeName(key) + ".img"), url, 0, true, callback);
	}

	public void loadWebsiteImage(String key, String url, String fallbackUrl, Consumer<BufferedImage> callback)
	{
		Filepath target = root.join("website-images", safeName(key) + ".img");
		load(target, url, 0, true, image ->
		{
			if (image != null) callback.accept(image);
			else load(target, fallbackUrl, 0, true, callback);
		});
	}

	private void load(Filepath target, String url, long ttl, boolean revalidate, Consumer<BufferedImage> callback)
	{
		executor.execute(() -> loadInBackground(target, url, ttl, revalidate, callback));
	}

	private void loadInBackground(Filepath target, String url, long ttl, boolean revalidate, Consumer<BufferedImage> callback)
	{
		BufferedImage cached = read(target);
		if (cached != null && !revalidate) callback.accept(cached);
		boolean fresh = false;
		try { fresh = ttl > 0 && target.exists() && System.currentTimeMillis() - target.getLastModifiedTime().toMillis() < ttl; }
		catch (IOException ignored) { }
		if (fresh || url == null || url.isBlank()) { if (cached == null || revalidate) callback.accept(null); return; }
		Request request;
		try
		{
			Request.Builder builder = new Request.Builder().url(url).get();
			if (revalidate) builder.header("Cache-Control", "no-cache, no-store").header("Pragma", "no-cache");
			request = builder.build();
		}
		catch (IllegalArgumentException e) { if (cached == null || revalidate) callback.accept(null); return; }
		http.newCall(request).enqueue(new Callback()
		{
			@Override public void onFailure(Call call, IOException e) { if (cached == null || revalidate) callback.accept(null); }
			@Override public void onResponse(Call call, Response response)
			{
				try (Response ignored = response)
				{
					if (!response.isSuccessful() || response.body() == null) { if (cached == null || revalidate) callback.accept(null); return; }
					target.getParent().createDirectories();
					Filepath temp = target.getParent().joinSegment(target.getFileName() + ".tmp");
					temp.write(response.body().bytes());
					BufferedImage downloaded = read(temp);
					if (downloaded == null) { temp.deleteIfExists(); if (cached == null || revalidate) callback.accept(null); return; }
					temp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
					callback.accept(downloaded);
				}
				catch (IOException e) { if (cached == null || revalidate) callback.accept(null); }
			}
		});
	}

	/**
	 * Loads raw image bytes into an ImageIcon so animated GIF frames remain animated.
	 * Network requests and file reads are handled off the Swing event thread.
	 */
	public void loadWebsiteIcon(String key, String url, Consumer<ImageIcon> callback)
	{
		Filepath target = root.join("website-images", safeName(key) + ".bin");
		executor.execute(() -> loadWebsiteIconInBackground(target, url, callback));
	}

	private void loadWebsiteIconInBackground(Filepath target, String url, Consumer<ImageIcon> callback)
	{
		// Only display artwork downloaded from the current backend. Never render a stale banner cache.
		if (url == null || url.isBlank()) { callback.accept(null); return; }

		Request request;
		try
		{
			request = new Request.Builder().url(url).get()
				.header("Cache-Control", "no-cache, no-store")
				.header("Pragma", "no-cache")
				.build();
		}
		catch (IllegalArgumentException e)
		{
			log.warn("Invalid animated banner URL for '{}'.", target.getFileName(), e);
			callback.accept(null);
			return;
		}

		http.newCall(request).enqueue(new Callback()
		{
			@Override public void onFailure(Call call, IOException e)
			{
				log.warn("Failed to download animated banner '{}'.", target.getFileName(), e);
				callback.accept(null);
			}

			@Override public void onResponse(Call call, Response response)
			{
				try (Response ignored = response)
				{
					if (!response.isSuccessful() || response.body() == null)
					{
						log.warn("Animated banner request returned HTTP {} (redirect: {}).",
							response.code(), response.header("Location"));
						callback.accept(null);
						return;
					}
					String contentType = response.header("Content-Type");
					byte[] bytes = response.body().bytes();
					AnimatedGifDisposalNormalizer.normalizeOpaqueFullFrameGifDisposal(bytes);
					int frames = gifFrameCount(bytes);
					ImageIcon downloaded = frames > 1 ? createIcon(bytes) : null;
					if (downloaded == null)
					{
						log.warn("Animated banner response is not an animated GIF (frames: {}, content-type: {}, bytes: {}).",
							frames, contentType, bytes.length);
						callback.accept(null);
						return;
					}
					log.debug("Downloaded animated banner ({} frames, {} bytes, {}x{}, content-type: {}).",
						frames, bytes.length, downloaded.getIconWidth(), downloaded.getIconHeight(), contentType);
					target.getParent().createDirectories();
					Filepath temp = target.getParent().joinSegment(target.getFileName() + ".tmp");
					temp.write(bytes);
					temp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
					callback.accept(downloaded);
				}
				catch (IOException e)
				{
					log.warn("Could not cache animated banner '{}'.", target.getFileName(), e);
					callback.accept(null);
				}
			}
		});
	}

	private static ImageIcon createIcon(byte[] bytes)
	{
		// Do not let an old/stale JPG cache be mistaken for an animated banner.
		if (!isGif(bytes)) return null;
		ImageIcon icon = new ImageIcon(bytes);
		return icon.getIconWidth() > 0 && icon.getIconHeight() > 0 ? icon : null;
	}


	private static boolean isGif(byte[] bytes)
	{
		if (bytes == null || bytes.length < 6) return false;
		boolean gif87a = bytes[0] == 'G' && bytes[1] == 'I' && bytes[2] == 'F'
			&& bytes[3] == '8' && bytes[4] == '7' && bytes[5] == 'a';
		boolean gif89a = bytes[0] == 'G' && bytes[1] == 'I' && bytes[2] == 'F'
			&& bytes[3] == '8' && bytes[4] == '9' && bytes[5] == 'a';
		return gif87a || gif89a;
	}

	private static int gifFrameCount(byte[] bytes)
	{
		if (!isGif(bytes)) return 0;
		try (ImageInputStream input = ImageIO.createImageInputStream(new ByteArrayInputStream(bytes)))
		{
			if (input == null) return 0;
			Iterator<ImageReader> readers = ImageIO.getImageReaders(input);
			if (!readers.hasNext()) return 0;
			ImageReader reader = readers.next();
			try
			{
				reader.setInput(input, false, false);
				return reader.getNumImages(true);
			}
			finally
			{
				reader.dispose();
			}
		}
		catch (IOException e)
		{
			log.warn("Could not inspect animated GIF frame count.", e);
			return 0;
		}
	}

	public void clear()
	{
		clear(null);
	}

	public void clear(Runnable afterClear)
	{
		executor.execute(() ->
		{
			deleteChildren(root);
			if (afterClear != null) afterClear.run();
		});
	}

	private static void deleteChildren(Filepath path)
	{
		if (!path.exists()) return;
		try (java.util.stream.Stream<Filepath> stream = path.walk())
		{
			stream.sorted(java.util.Comparator.reverseOrder())
				.filter(p -> !p.equals(path))
				.forEach(p -> { try { p.deleteIfExists(); } catch (IOException ignored) { } });
		}
		catch (IOException ignored) { }
	}

	private static BufferedImage read(Filepath path)
	{
		if (!path.isFile()) return null;
		try (var input = path.openInputStream()) { return ImageIO.read(input); }
		catch (IOException e) { return null; }
	}

	public static String safeName(String value)
	{
		String normalized = value == null ? "unknown" : value.trim().toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9_-]+", "_");
		return normalized.isEmpty() ? "unknown" : normalized;
	}
}

package com.zweetnekken.service;

import com.zweetnekken.model.ZweetnekkenModels;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;

/** Selects loot worth submitting without assigning or estimating points. */
public final class LootEligibility
{
	/**
	 * Custom loot values supplied by the clan. These matchers intentionally bypass
	 * both the GE threshold and the tradeable check. The source list uses regular
	 * expressions, so keep matching case-insensitive and use find() rather than
	 * requiring an exact item-name match.
	 */
	private static final List<Pattern> ALWAYS_SUBMIT = Arrays.asList(
		Pattern.compile("prayer scroll", Pattern.CASE_INSENSITIVE),
		Pattern.compile("dinh's bulwark", Pattern.CASE_INSENSITIVE),
		Pattern.compile("twisted buckler", Pattern.CASE_INSENSITIVE),
		Pattern.compile("dragon hunter crossbow", Pattern.CASE_INSENSITIVE),
		Pattern.compile("dragon claws", Pattern.CASE_INSENSITIVE),
		Pattern.compile("kodai insignia", Pattern.CASE_INSENSITIVE),
		Pattern.compile("twisted kit", Pattern.CASE_INSENSITIVE),
		Pattern.compile("metamorphic dust", Pattern.CASE_INSENSITIVE),
		Pattern.compile("justiciar", Pattern.CASE_INSENSITIVE),
		Pattern.compile("sanguinesti staff", Pattern.CASE_INSENSITIVE),
		Pattern.compile("ghrazi rapier", Pattern.CASE_INSENSITIVE),
		Pattern.compile("sanguine ornament kit", Pattern.CASE_INSENSITIVE),
		Pattern.compile("holy ornament kit", Pattern.CASE_INSENSITIVE),
		Pattern.compile("sanguine dust", Pattern.CASE_INSENSITIVE),
		Pattern.compile("lightbearer", Pattern.CASE_INSENSITIVE),
		Pattern.compile("osmumten's fang", Pattern.CASE_INSENSITIVE),
		Pattern.compile("elidinis' ward", Pattern.CASE_INSENSITIVE),
		Pattern.compile("masori mask", Pattern.CASE_INSENSITIVE),
		Pattern.compile("masori chaps", Pattern.CASE_INSENSITIVE),
		Pattern.compile("masori body", Pattern.CASE_INSENSITIVE),
		Pattern.compile("inquisitor", Pattern.CASE_INSENSITIVE),
		Pattern.compile("nightmare staff", Pattern.CASE_INSENSITIVE),
		// Only the Nightmare unique orbs belong here; matching the bare word
		// "orb" also captures ordinary Air orb and Earth orb drops.
		Pattern.compile("^(?:eldritch|harmonised|volatile) orb$", Pattern.CASE_INSENSITIVE),
		Pattern.compile("parasitic egg", Pattern.CASE_INSENSITIVE),
		Pattern.compile("zulrah mutagen", Pattern.CASE_INSENSITIVE),
		Pattern.compile("infernal cape", Pattern.CASE_INSENSITIVE),
		Pattern.compile("dizana's quiver", Pattern.CASE_INSENSITIVE),
		Pattern.compile("sunfire fanatic helm", Pattern.CASE_INSENSITIVE),
		Pattern.compile("sunfire fanatic cuirass", Pattern.CASE_INSENSITIVE),
		Pattern.compile("sunfire fanatic chausses", Pattern.CASE_INSENSITIVE),
		Pattern.compile("echo crystal", Pattern.CASE_INSENSITIVE),
		Pattern.compile("tonalztics of ralos", Pattern.CASE_INSENSITIVE),
		Pattern.compile("araxyte fang", Pattern.CASE_INSENSITIVE),
		Pattern.compile("mokhaiotl cloth", Pattern.CASE_INSENSITIVE),
		Pattern.compile("ultor vestige", Pattern.CASE_INSENSITIVE),
		Pattern.compile("venator vestige", Pattern.CASE_INSENSITIVE),
		// The supplied list spells these two as "vestage"; support the game name
		// as well as the source spelling.
		Pattern.compile("magus vest(?:i|a)ge", Pattern.CASE_INSENSITIVE),
		Pattern.compile("bellator vest(?:i|a)ge", Pattern.CASE_INSENSITIVE),
		Pattern.compile("twisted ancestral colour kit", Pattern.CASE_INSENSITIVE),
		Pattern.compile("crimson kisten", Pattern.CASE_INSENSITIVE),
		Pattern.compile("etched elder venator fang", Pattern.CASE_INSENSITIVE),
		Pattern.compile("jar of (?:venom|swamp|stone|spirits|souls|smoke|sand|miasma|feathers|eyes|dreams|dirt|decay|darkness|chemicals|light)", Pattern.CASE_INSENSITIVE),
		Pattern.compile("mr mcgroot", Pattern.CASE_INSENSITIVE),
		Pattern.compile("aggy", Pattern.CASE_INSENSITIVE),
		// Untradeable rare drops can have a low or zero GE price, but are still
		// meaningful collection-log loot and should be captured on every drop.
		Pattern.compile("elder venator fang", Pattern.CASE_INSENSITIVE)
	);

	private LootEligibility() {}

	public static boolean isAlwaysSubmit(String itemName)
	{
		if (itemName == null || itemName.isBlank()) return false;
		return ALWAYS_SUBMIT.stream().anyMatch(pattern -> pattern.matcher(itemName).find());
	}

	public static boolean shouldCapture(ZweetnekkenModels.Item item, ZweetnekkenModels.Rules rules)
	{
		if (item == null || rules == null) return false;
		String name = item.name == null ? "" : item.name.trim().toLowerCase(Locale.ROOT);
		if (isAlwaysSubmit(name)) return true;
		return item.tradeable && item.quantity >= 1 && meetsMinimumValue(item, rules);
	}

	/** Value-only check used when a collection-log unlock must be promoted to clan-point loot. */
	public static boolean meetsMinimumValue(ZweetnekkenModels.Item item, ZweetnekkenModels.Rules rules)
	{
		return item != null && rules != null && item.unitGeValue >= rules.minimumLootValue;
	}
}

