		ids.put("corrupted_gauntlet", 4295); ids.put("hueycoatl", 5640); ids.put("leviathan", 5633);
		ids.put("royal_titans", 6345); ids.put("whisperer", 5631); ids.put("theatre_of_blood", 4290);
